export const handleGroupCommands = async (sock, msg, remoteJid, command, args, isOwner) => {
    if (!remoteJid.endsWith('@g.us')) return;

    try {
        const groupMetadata = await sock.groupMetadata(remoteJid);
        const participants = groupMetadata.participants || [];

        // 🎯 SOLUTION DÉFINITIVE SELF-BOT :
        // 1. Déduction de l'expéditeur réel
        const senderJid = msg.key.participant || remoteJid;
        const senderNumber = senderJid.split(':')[0].split('@')[0];

        // 2. Recherche du statut Admin dans la liste du groupe
        const senderParticipant = participants.find(p => p.id.includes(senderNumber));
        const isUserAdminInGroup = senderParticipant?.admin === 'admin' || senderParticipant?.admin === 'superadmin';

        // 3. En Self-Bot : Si tu es l'Owner (isOwner) ET admin du groupe, alors le Bot a automatiquement les droits Admin.
        const isSenderAdmin = isOwner || isUserAdminInGroup;
        const isBotAdmin = isOwner ? isUserAdminInGroup : (participants.find(p => p.id.includes(sock.user.id.split(':')[0].split('@')[0]))?.admin !== undefined);

        switch (command) {

            // --- KICK ---
            case 'kick': {
                if (!isSenderAdmin) {
                    await react(sock, msg, '❌');
                    return await sock.sendMessage(remoteJid, { text: '⚠️ *Tu dois être Administrateur du groupe pour exécuter cette commande.*' }, { quoted: msg });
                }
                if (!isBotAdmin) {
                    await react(sock, msg, '🚫');
                    return await sock.sendMessage(remoteJid, { text: '⚠️ *Assure-toi d\'être Administrateur dans les paramètres du groupe.*' }, { quoted: msg });
                }

                const target = getTargetJid(msg, args);
                if (!target) {
                    return await sock.sendMessage(remoteJid, { text: '⚠️ *Mentionne ou réponds au message du membre à expulser.*' }, { quoted: msg });
                }

                await sock.groupParticipantsUpdate(remoteJid, [target], 'remove');
                await react(sock, msg, '✅');
                await sock.sendMessage(remoteJid, { text: `🚪 *@${target.split('@')[0]} a été expulsé.*`, mentions: [target] });
                break;
            }

            // --- ADD ---
            case 'add': {
                if (!isSenderAdmin || !isBotAdmin) {
                    return await sock.sendMessage(remoteJid, { text: '⚠️ *Tu dois être Administrateur du groupe.*' }, { quoted: msg });
                }

                const target = getTargetJid(msg, args);
                if (!target) {
                    return await sock.sendMessage(remoteJid, { text: '⚠️ *Spécifie le numéro à ajouter.* Exemple : `.add 241xxxxxxx`' }, { quoted: msg });
                }

                await sock.groupParticipantsUpdate(remoteJid, [target], 'add');
                await react(sock, msg, '✅');
                break;
            }

            // --- PROMOTE ---
            case 'promote': {
                if (!isSenderAdmin || !isBotAdmin) return;
                const target = getTargetJid(msg, args);
                if (!target) return;

                await sock.groupParticipantsUpdate(remoteJid, [target], 'promote');
                await react(sock, msg, '👑');
                await sock.sendMessage(remoteJid, { text: `👑 *@${target.split('@')[0]} est désormais Administrateur.*`, mentions: [target] });
                break;
            }

            // --- DEMOTE ---
            case 'demote': {
                if (!isSenderAdmin || !isBotAdmin) return;
                const target = getTargetJid(msg, args);
                if (!target) return;

                await sock.groupParticipantsUpdate(remoteJid, [target], 'demote');
                await react(sock, msg, '📉');
                await sock.sendMessage(remoteJid, { text: `📉 *@${target.split('@')[0]} n'est plus Administrateur.*`, mentions: [target] });
                break;
            }

            // --- MUTE & UNMUTE ---
            case 'mute': {
                if (!isSenderAdmin || !isBotAdmin) return;
                await sock.groupSettingUpdate(remoteJid, 'announcement');
                await react(sock, msg, '🔒');
                await sock.sendMessage(remoteJid, { text: '🔒 *Le groupe a été fermé. Seuls les admins peuvent envoyer des messages.*' });
                break;
            }

            case 'unmute': {
                if (!isSenderAdmin || !isBotAdmin) return;
                await sock.groupSettingUpdate(remoteJid, 'not_announcement');
                await react(sock, msg, '🔓');
                await sock.sendMessage(remoteJid, { text: '🔓 *Le groupe a été ouvert à tous les membres.*' });
                break;
            }

            // --- TAGALL ---
            case 'tagall': {
                if (!isSenderAdmin) return;

                let text = `📢 *CONVOCATION GÉNÉRALE*\n\n💬 *Message :* ${args.join(' ') || 'Aucun'}\n\n`;
